import React, { useState, useEffect } from 'react';
import { getStore1CategoryStocks } from '../services/stockService';

const CategoryStockDashboard = () => {
    const [categoryStocks, setCategoryStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchCategoryStocks = async () => {
            try {
                const response = await getStore1CategoryStocks();
                console.log('API Response:', response); // Debug için
                
                if (response && response.categoryStocks) {
                    setCategoryStocks(response.categoryStocks);
                    setError(null);
                } else {
                    setError('Veri formatı beklenen şekilde değil');
                }
            } catch (err) {
                console.error('API Error:', err); // Debug için
                setError('Kategori stokları yüklenirken bir hata oluştu');
            } finally {
                setLoading(false);
            }
        };

        fetchCategoryStocks();
    }, []);

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
                <strong className="font-bold">Hata!</strong>
                <span className="block sm:inline"> {error}</span>
            </div>
        );
    }

    if (!categoryStocks || categoryStocks.length === 0) {
        return (
            <div className="text-center py-8">
                <h2 className="text-2xl font-bold mb-4">Store 1 Kategori Stok Durumu</h2>
                <p className="text-gray-600">Henüz kategori stok bilgisi bulunmamaktadır.</p>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8">
            <h2 className="text-2xl font-bold mb-6">Store 1 Kategori Stok Durumu</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {categoryStocks.map((stock, index) => (
                    <div
                        key={index}
                        className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition-shadow duration-300"
                    >
                        <h3 className="text-xl font-semibold text-gray-800 mb-2">{stock.category || 'Kategorisiz'}</h3>
                        <div className="flex items-center justify-between">
                            <span className="text-gray-600">Toplam Stok:</span>
                            <span className="text-2xl font-bold text-blue-600">{stock.totalQuantity || 0}</span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default CategoryStockDashboard;
